<?php require 'includes/auth.php'; require_login(); require 'config/db.php'; include 'includes/header.php'; $code=$_GET['code']??''; $stmt=$conn->prepare('SELECT * FROM inventory_transactions WHERE item_code=? ORDER BY transaction_date DESC'); $stmt->bind_param('s',$code); $stmt->execute(); $rs=$stmt->get_result(); ?>
